import{_ as d,o as e,c as a,ag as i}from"./chunks/framework.Drp2S_UI.js";const m=JSON.parse('{"title":"main 合入与渲染引擎适配记录（2026-10-16）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/main-integration-2026-10-16.md","filePath":"guide/main-integration-2026-10-16.md","lastUpdated":1792653875000}'),r={name:"guide/main-integration-2026-10-16.md"};function o(l,t,n,c,h,u){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="main-合入与渲染引擎适配记录-2026-10-16" tabindex="-1">main 合入与渲染引擎适配记录（2026-10-16） <a class="header-anchor" href="#main-合入与渲染引擎适配记录-2026-10-16" aria-label="Permalink to &quot;main 合入与渲染引擎适配记录（2026-10-16）&quot;">​</a></h1><blockquote><p>历史方案/基线记录，保留当时结论供审计。旧引擎、模式选择与浏览器文字回退 已由 T20 删除；当前 API、字体能力与示例以<a href="./font-and-esm-migration.html">迁移指南</a>为准。</p></blockquote><h2 id="对比基线" tabindex="-1">对比基线 <a class="header-anchor" href="#对比基线" aria-label="Permalink to &quot;对比基线&quot;">​</a></h2><ul><li>目标分支：<code>refactor/canvas-render-engine</code>，合入前为 <code>8b473f85</code>。</li><li>远程：<code>origin</code>（<code>HerbertHe/canvas-editor</code>）。</li><li>最新 main：<code>1d7cd1a7</code>，共同祖先：<code>21bed9ba</code>。</li><li>main 新增 45 个提交，变更 130 个文件。采用完整合并，保留上游历史。</li></ul><h2 id="影响范围与适配" tabindex="-1">影响范围与适配 <a class="header-anchor" href="#影响范围与适配" aria-label="Permalink to &quot;影响范围与适配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>main 改动</th><th>影响范围</th><th>本分支适配</th></tr></thead><tbody><tr><td>段前/段后间距与装饰修复</td><td>元素属性、段落命令、行高、分页、命中、高亮、下划线、选区</td><td>为 HarfBuzz 段落补齐缩放后的首行偏移与末行间距；视觉装饰剔除段后间距；段前空白按逻辑段首定位，兼容 RTL</td></tr><tr><td>行级增量布局</td><td>Draw、脏区间追踪、行快照、分页前原始行、位置缓存、编辑命令</td><td>legacy 启用上游算法；续算时保留复用行的布局字段；HarfBuzz 自动回退全量；布局签名加入引擎类型，避免切换引擎后使用旧快照</td></tr><tr><td>可配置拼写检查</td><td>光标代理、错词 API、renderChange/spellcheckClick、词典插件、工具栏</td><td>保留 API 和词典依赖；波浪线按视觉坐标合并区间，支持 RTL 并避免跨 BiDi 空隙连线</td></tr><tr><td>元素/控件/单元格悬浮提示</td><td>元素模型、格式化、鼠标移动、提示弹窗、销毁</td><td>与原有复选框 pointer 和留痕提示共存</td></tr><tr><td>单元格边框颜色与宽度</td><td>单元格数据、命令、表格绘制、工具栏</td><td>保留已有表格镜像；合并拖拽宽度修复，按缩放后的逻辑位移计算最小列宽</td></tr><tr><td>控件背景配置与溢出修复</td><td>控件配置、行高亮、命令、序列化</td><td>保留引擎视觉矩形计算，同时使用上游控件颜色与高亮刷新规则</td></tr><tr><td>Shift 选区锚点修复</td><td>mousedown、上下方向键、滚动、跨表格选区</td><td>保留固定锚点，同时保留点击复选框/标签切换时隐藏光标的分支行为</td></tr><tr><td>光标待输入格式、历史关闭优化</td><td>格式切换、快照提交</td><td>合入共享命令与历史路径，适用于两种引擎</td></tr><tr><td>控件赋值覆盖选项、环绕元素/组矩形 API</td><td>公共命令与类型导出、控制值更新、区域坐标</td><td>与段落方向查询 API 同时保留</td></tr><tr><td>级联函数扩展、表格标识序列化修复</td><td>表达式求值、extraPickAttrs、嵌套表格数据</td><td>合入上游实现与测试</td></tr><tr><td>日期、图片标题、空表格行等修复</td><td>弹窗、图片粒子、表格操作、搜索与范围处理</td><td>解决与分支 RTL 弹窗/表格工具的重叠；行号沿用 RTL 位置并修正重复缩放</td></tr><tr><td>依赖、文档与示例更新</td><td>package、锁文件、文档导航、宿主页面</td><td>合并全部依赖并保留 bidi-js/harfbuzzjs/opentype.js；同时保留新功能文档与 RTL 架构文档入口</td></tr></tbody></table><h2 id="兼容性边界" tabindex="-1">兼容性边界 <a class="header-anchor" href="#兼容性边界" aria-label="Permalink to &quot;兼容性边界&quot;">​</a></h2><p>以下为 main 合并时的状态。后续已加入 HarfBuzz 段落级增量适配， 当前能力及限制见 <a href="./harfbuzz-incremental-layout.html">HarfBuzz 增量排版</a>。</p><p><code>lab.incrementalCompute</code> 默认关闭。打开后，legacy 简单文本使用上游增量算法； <code>textEngine: &#39;harfbuzz&#39;</code> 始终完整排版，因此不会获得本次上游增量算法的性能收益。 HarfBuzz 段落整形与 BiDi 重排不满足 legacy 行快照的恢复条件，需要独立设计增量策略。</p><p>保留当前分支的字体注册、UI 方向与内容方向分离、视觉光标与删除、混合纸张方向、 表格镜像、控件缩进和复选框交互。核心 text-engine 整形模块没有被 main 覆盖。</p><h2 id="回归覆盖" tabindex="-1">回归覆盖 <a class="header-anchor" href="#回归覆盖" aria-label="Permalink to &quot;回归覆盖&quot;">​</a></h2><ul><li>上游全量单元测试及本分支原有 RTL/整形/分页/交互测试。</li><li>新增 LTR/RTL 双方向段落间距、缩放、高亮高度、空白命中回归。</li><li>新增 HarfBuzz 在增量开关开启时编辑后与全量排版一致的回归。</li><li>新增整形文本 Shift 点击固定锚点回归。</li><li>新增 RTL 错词波浪线和 BiDi 非连续视觉区间回归。</li><li>增量差分测试按对象键排序比较，消除重新写入布局字段导致的 JSON 键顺序差异； 行/元素数组顺序与字段值仍完整比较。</li></ul><h2 id="验证结果与已有构建限制" tabindex="-1">验证结果与已有构建限制 <a class="header-anchor" href="#验证结果与已有构建限制" aria-label="Permalink to &quot;验证结果与已有构建限制&quot;">​</a></h2><ul><li>ESLint 与 TypeScript 检查通过；121 个测试文件、716 项单元测试全部通过。</li><li><code>vite build --mode app</code> 通过。</li><li><code>npm run lib</code> 的检查、单测和 ES 模块生成完成，但 UMD 输出失败： <code>harfbuzzjs@1.4.0</code> 的模块入口包含顶层 <code>await</code>，无法打包进 UMD。 使用合并前 <code>8b473f85</code> 源码及当前安装的构建工具也复现相同错误； 当前 HarfBuzz 依赖和静态导入方式需要单独处理 UMD 初始化策略。</li><li>检查基线检出时发现 <code>LayoutCache.ts</code> 被通用 <code>cache</code> 规则忽略，本次为该源码目录 添加精确例外并纳入版本控制，防止新检出环境缺少模块。</li><li>未运行浏览器端 Cypress 测试。</li></ul>',14)])])}const f=d(r,[["render",o]]);export{m as __pageData,f as default};
